from json import dumps
from collections import deque


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        # Sort children for consistent representation and comparison
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        # Allows sorting Tree objects by their label
        return self.label < other.label

    def __eq__(self, other):
        # Allows comparing Tree objects based on their dictionary representation
        return self.__dict__() == other.__dict__()

    def _build_adj_graph(self):
        """
        Builds an undirected adjacency graph (dictionary) from the current Tree structure
        and returns a set of all node labels present in the tree.
        The graph maps each node label to a set of its direct neighbor labels.
        """
        graph = {}  # label -> set of neighbor labels
        all_nodes = set()  # all node labels found in the tree

        def dfs_build(node_obj, parent_label=None):
            current_label = node_obj.label
            all_nodes.add(current_label)

            if current_label not in graph:
                graph[current_label] = set()

            if parent_label is not None:
                # Add bidirectional edge between current node and its parent
                graph[current_label].add(parent_label)
                if parent_label not in graph:
                    graph[parent_label] = set()
                graph[parent_label].add(current_label)

            # Recurse for children
            for child_obj in node_obj.children:
                dfs_build(child_obj, current_label)

        dfs_build(self, None)  # Start DFS from the current root of this Tree instance
        return graph, all_nodes

    def from_pov(self, from_node):
        """
        Reorients the tree, returning a new Tree object with 'from_node' as its root.
        """
        graph, all_nodes = self._build_adj_graph()

        if from_node not in all_nodes:
            raise ValueError("Tree could not be reoriented")

        # Recursive helper to build the new Tree structure rooted at `current_label`.
        # `parent_label_in_new_tree` is the label of the node that is the parent
        # of `current_label` in the *new* tree being built. This helps prevent
        # traversing back up the newly established parent-child link.
        def build_new_tree_dfs(current_label, parent_label_in_new_tree):
            new_node = Tree(current_label)

            for neighbor_label in graph[current_label]:
                if neighbor_label != parent_label_in_new_tree:
                    # Recursively build child nodes and append them
                    child_node = build_new_tree_dfs(neighbor_label, current_label)
                    new_node.children.append(child_node)

            return new_node

        return build_new_tree_dfs(from_node, None)

    def path_to(self, from_node, to_node):
        """
        Finds the unique path from 'from_node' to 'to_node' in the tree.
        Returns a list of node labels representing the path.
        """
        graph, all_nodes = self._build_adj_graph()

        if from_node not in all_nodes or to_node not in all_nodes:
            raise ValueError("No path found")

        # Use BFS to find the path, as it's guaranteed to find the shortest (and only) path in a tree
        queue = deque([(from_node, [from_node])])  # (current_node_label, path_list_so_far)
        visited = {from_node}  # Keep track of visited nodes to avoid cycles and redundant work

        while queue:
            current_label, path = queue.popleft()

            if current_label == to_node:
                return path

            for neighbor_label in graph[current_label]:
                if neighbor_label not in visited:
                    visited.add(neighbor_label)
                    new_path = path + [neighbor_label]
                    queue.append((neighbor_label, new_path))

        # This point should theoretically not be reached if from_node and to_node
        # are valid nodes in a connected tree. However, it serves as a robust fallback.
        raise ValueError("No path found")

